#include <iostream>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "syrk.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization, translated from the original C version.
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < m; j++)
 *       A[i][j] = ((i*j+1)%n) / n;
 *
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       C[i][j] = ((i*j+2)%m) / m;
 *
 * Mapping to Halide:
 *   C-array A[i][j] -> Buffer A(j, i) with shape (m, n)
 *   C-array C[i][j] -> Buffer C(j, i) with shape (n, n)
 */
static
void init_array(int n, int m,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // A(i,j) initialization mapped to A(j, i) in the Buffer.
    // We keep the original integer arithmetic and then cast to num_t.
    init_A(j, i) =
        cast<num_t>(((i * j + 1) % n)) / cast<num_t>(n);

    // C(i,j) initialization mapped to C(j, i) in the Buffer.
    init_C(j, i) =
        cast<num_t>(((i * j + 2) % m)) / cast<num_t>(m);

    // Simple but decently efficient schedule for initialization:
    // - parallelize over the outer (row) dimension
    // - vectorize along the inner (contiguous) dimension
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size (from PolyBench or similar definitions)
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Bind ImageParams to the initialized Buffers
    C_param.set(C);
    A_param.set(A);

    // Halide Vars
    Var i("i"), j("j");

    // Build the SYRK kernel in Halide
    //
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    //   for (i = 0; i < _PB_N; i++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] *= beta;
    //     for (k = 0; k < _PB_M; k++) {
    //       for (j = 0; j <= i; j++)
    //         C[i][j] += alpha * A[i][k] * A[j][k];
    //     }
    //   }
    //
    // Mapping:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We explicitly model the *triangular* update domain using
    // reduction domains with predicates (RDom::where), instead of
    // computing over the full N x N box and masking with select().
    // This avoids doing useless work on the upper triangle and
    // matches the original C algorithm's complexity.

    Func syrk("syrk");

    // Treat alpha and beta as constants within the Halide pipeline.
    const Expr alpha_expr = cast<num_t>(alpha);
    const Expr beta_expr  = cast<num_t>(beta);

    // Pure definition: start from the original C matrix everywhere.
    // syrk(j, i) corresponds to C[i][j].
    syrk(j, i) = C_param(j, i);

    // First update: scale the lower triangle by beta.
    // Domain: 0 <= j < n, 0 <= i < n, with j <= i.
    RDom r_beta(0, n, 0, n, "r_beta");
    r_beta.where(r_beta.x <= r_beta.y);  // x -> j, y -> i

    syrk(r_beta.x, r_beta.y) =
        syrk(r_beta.x, r_beta.y) * beta_expr;

    // Second update: add alpha * A[i][k] * A[j][k] for the lower triangle.
    //
    // Domain: 0 <= j < n, 0 <= i < n, 0 <= k < m, with j <= i.
    // RDom coordinates: (x=j, y=i, z=k).
    RDom r_syrk(0, n, 0, n, 0, m, "r_syrk");
    r_syrk.where(r_syrk.x <= r_syrk.y);

    syrk(r_syrk.x, r_syrk.y) +=
        alpha_expr *
        A_param(r_syrk.z, r_syrk.y) *  // A[i][k]  -> A_param(k, i)
        A_param(r_syrk.z, r_syrk.x);   // A[j][k]  -> A_param(k, j)

    // ------------------------------------------------------------------
    // Schedule
    // ------------------------------------------------------------------
    //
    // Goals:
    //  - Exploit data locality in C and A.
    //  - Parallelize across the i (row) dimension.
    //  - Vectorize along the contiguous j (column / x) dimension.
    //  - Avoid redundant work on the upper triangle (achieved via RDom::where).
    //
    // Notes on layout:
    //  - Buffers are laid out with dimension 0 (x) contiguous in memory.
    //    For C(j, i): j is contiguous, i is strided.
    //    For A(k, i): k is contiguous, i is strided.

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tunable tile sizes (chosen to balance cache locality and parallelism).
    const int tile_j = 64;  // along contiguous dimension
    const int tile_i = 32;  // along strided dimension

    Var jo("jo"), io("io"), ji("ji"), ii("ii");

    // Compute syrk at the root; tile and parallelize over tiles of rows.
    syrk
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .parallel(io)              // parallel over tiles of rows
        .vectorize(ji, vec_width); // vectorize along contiguous j within tile

    // Schedule for the first update (beta scaling):
    // Iterate over i (rows) in parallel, vectorize over j (columns).
    //
    // We reorder so that j (r_beta.x) is innermost and thus a good
    // target for vectorization; i (r_beta.y) is outer and parallel.
    syrk.update(0)
        .reorder(r_beta.x, r_beta.y)
        .vectorize(r_beta.x, vec_width)
        .parallel(r_beta.y);

    // Schedule for the second update (rank-k update):
    //
    // We want:
    //   outer : i  (r_syrk.y)
    //   middle: j  (r_syrk.x)   -- vectorized
    //   inner : k  (r_syrk.z)   -- reduction dimension
    //
    // so we reorder with arguments listed from innermost to outermost:
    //   reorder(r_syrk.z, r_syrk.x, r_syrk.y)
    // gives loops:
    //   for i (r_syrk.y)
    //     for j (r_syrk.x)  [vectorized]
    //       for k (r_syrk.z)
    //
    // This:
    //  - Parallelizes across rows (i)
    //  - Vectorizes along contiguous C's j dimension
    //  - Keeps the reduction over k innermost for good temporal locality
    //    when streaming A(k, i) and A(k, j).
    syrk.update(1)
        .reorder(r_syrk.z, r_syrk.x, r_syrk.y)
        .vectorize(r_syrk.x, vec_width)
        .parallel(r_syrk.y);

    // Compile the kernel to machine code for the current host
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
