/**
 * Array initialization, translated from the original C version.
 *
 * C version:
 *   alpha = 1.5; beta = 1.2;
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < m; j++)
 *       A[i][j] = ((i*j+1)%n) / n;
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       C[i][j] = ((i*j+2)%m) / m;
 *
 * Mapping to Halide Buffers (row-major):
 *   C[i][j] in C     -> C(j, i)  with shape (n, n)
 *   A[i][j] in C     -> A(j, i)  with shape (m, n)
 */
static
void init_array(int n, int m,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // Precompute reciprocals once as Exprs to avoid repeated divisions.
    Expr inv_n = cast<num_t>(1) / cast<num_t>(n);
    Expr inv_m = cast<num_t>(1) / cast<num_t>(m);

    // A[i][j] = ((i*j+1)%n) / n;
    // C array A[i][j] is mapped to Buffer A(j, i) with shape (m, n).
    init_A(j, i) = cast<num_t>((i * j + 1) % n) * inv_n;

    // C[i][j] = ((i*j+2)%m) / m;
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>((i * j + 2) % m) * inv_m;

    // Simple but reasonably efficient schedule for initialization:
    // - j is the innermost, contiguous dimension (dim 0), so we vectorize it.
    // - we parallelize across rows (i).
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    init_A.compute_root()
          .reorder(j, i)
          .vectorize(j, vec)
          .parallel(i);

    init_C.compute_root()
          .reorder(j, i)
          .vectorize(j, vec)
          .parallel(i);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // Reduction over the M dimension (original k-loop).
    RDom k(0, A.dim(0).extent(), "k"); // k over M (first dimension of A)

    // Build the SYRK kernel in Halide
    // BLAS SYRK (lower triangular, no transpose):
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    //   C_new[i][j] = C[i][j]                                             if j > i
    //               = beta * C[i][j] + alpha * sum_k A[i][k] * A[j][k]   if j <= i
    //
    // Remember mapping:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We'll compute a full N x N Func, and use select(j <= i, ..., orig)
    // to restrict updates to the lower triangle while leaving the upper
    // triangle untouched.

    Func syrk("syrk");

    // Lift host scalars into Halide Exprs once.
    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // Original C value at (i, j) in row-major is C_param(j, i) here.
    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        beta_expr * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for the lower triangle.
    // Note: we still iterate over all j, but only contribute for j <= i.
    syrk(j, i) += select(j <= i,
                         alpha_expr * A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // ----------------------
    // Scheduling the kernel
    // ----------------------
    //
    // Goals:
    //   - Good data locality w.r.t. row-major storage (dim 0 is contiguous).
    //   - Vectorize along j (contiguous in C).
    //   - Parallelize across rows (i), which are independent.
    //   - Keep a traversal order reasonably close to the original C code
    //     (i outermost, j inner for the pure step; i outer, k mid, j inner
    //     for the update).
    //
    // Note: we intentionally parallelize only over i; parallelizing over k
    // in the reduction would require rfactor-style transformations.

    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Compute the entire syrk Func at the root.
    syrk.compute_root();

    // Pure step schedule: for i in [0..n), j in [0..n).
    //   - j is the innermost loop (contiguous), so we vectorize it.
    //   - i is parallel outer loop over rows.
    syrk
        .reorder(j, i)       // inner -> outer: j, i
        .vectorize(j, vec)
        .parallel(i);

    // Update step schedule (reduction over k):
    //   Loops become (from outer to inner): i, k, j
    //   - i outermost and parallel.
    //   - j innermost and vectorized for good C memory access.
    //   - k is the serial reduction dimension.
    syrk.update()
        .reorder(j, k, i)    // inner -> outer: j, k, i  => for (i) for (k) for (j)
        .vectorize(j, vec)
        .parallel(i);

    // Bind ImageParams
    C_param.set(C);
    A_param.set(A);

    // Compile the kernel to machine code for the chosen target (outside timing).
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t. the original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
