#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "syrk.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization, translated from the original C version.
 *
 * We express the initialization as Halide pipelines and add a simple
 * schedule to get vectorization + parallelization over rows.
 */
static void init_array(int n, int m,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < m; j++)
    //     A[i][j] = ((i*j+1)%n) / n;
    //
    // C array A[i][j] is mapped to Buffer A(j, i) with shape (m, n).
    init_A(j, i) = cast<num_t>(((i * j + 1) % n)) / cast<int>(n);

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>(((i * j + 2) % m)) / cast<int>(m);

    // -------- Scheduling for initialization --------
    //
    // We want:
    //   - j as the innermost loop, because dimension 0 (j) is contiguous.
    //   - vectorization in j.
    //   - parallelization over rows (i).
    Target init_target = get_jit_target_from_environment();
    int vec_width = init_target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // A is m x n (j: 0..m-1, i: 0..n-1).
    init_A
        .compute_root()
        .bound(i, 0, n)
        .bound(j, 0, m)
        .reorder(j, i)
        .vectorize(j, vec_width)
        .parallel(i);

    // C is n x n (j: 0..n-1, i: 0..n-1).
    init_C
        .compute_root()
        .bound(i, 0, n)
        .bound(j, 0, n)
        .reorder(j, i)
        .vectorize(j, vec_width)
        .parallel(i);

    // Execute initializations
    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Bind ImageParams to the initialized Buffers
    C_param.set(C);
    A_param.set(A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k runs over M (first dimension of A)
    RDom k(0, m, "k");

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    //   C_new[i][j] = C[i][j]                                       if j > i
    //               = beta * C[i][j] +
    //                 alpha * sum_k A[i][k] * A[j][k]               if j <= i
    //
    // Mapping to Buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We compute a full N x N Func and use select(j <= i, ..., orig)
    // to restrict updates to the lower triangle. This keeps the code
    // simple while preserving the original semantics.

    Func syrk("syrk");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper
    // triangle unchanged.
    syrk(j, i) = select(j <= i,
                        cast<num_t>(beta_expr) * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for lower triangle.
    syrk(j, i) += select(j <= i,
                         cast<num_t>(alpha_expr) *
                             A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // -------- Scheduling for SYRK --------
    //
    // Data layout:
    //   - C and syrk are stored as C(j, i): dim 0 (j) contiguous, dim 1 (i) strided.
    //   - A is stored as A(k, i): dim 0 (k) contiguous, dim 1 (i) strided.
    //
    // Goals:
    //   - Access C and syrk with j as the innermost loop for good locality + vectorization.
    //   - Keep k innermost wrt A to get streaming access along A's contiguous dimension.
    //   - Parallelize across rows i (independent outputs).
    //
    // We do:
    //   Pure step  : outer i (parallel), inner j (vectorized).
    //   Update step: outer i (parallel), then k, then j (vectorized).
    //
    // Note: j <= i triangular condition is handled via select;
    // extra work on the upper triangle does not affect correctness.

    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // Bound the iteration domain explicitly to help the compiler.
    syrk
        .compute_root()
        .bound(i, 0, n)
        .bound(j, 0, n)
        // Make j the innermost loop (fast dimension).
        .reorder(j, i)
        // Vectorize across contiguous j.
        .vectorize(j, vec_width)
        // Parallelize across rows i.
        .parallel(i);

    // Schedule the reduction update.
    syrk.update()
        // Loop order: i (outer, parallel), k, then j (innermost).
        .reorder(j, k, i)
        // Vectorize across j (contiguous dimension).
        .vectorize(j, vec_width)
        // Parallelize across i (rows are independent).
        .parallel(i);

    // Compile the kernel to machine code for the chosen target.
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place w.r.t. caller's view)
    // Note: The algorithm effectively uses the original C only as the
    // starting point (scaled by beta) and then accumulates the rank-k
    // update on top, which is algebraically equivalent to the original
    // loop nest.
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

