    // Treat alpha and beta as Halide Exprs of the same type as the data.
    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // Pure definition: start from the original matrix C.
    // This copies C into syrk; later update definitions will overwrite the
    // lower triangle in-place, mirroring the original in-place kernel.
    syrk(j, i) = C_param(j, i);

    // === First update: scale the lower triangle by beta ===
    //
    // We use a 2D RDom over (row=i, col=j), but restrict it to the lower
    // triangle via .where(r.y <= r.x). Using RDom::where means that for
    // positions outside the triangle we only pay the cost of an "if"
    // check; no multiplications or loads are done there.
    RDom r_scale(0, n, 0, n, "r_scale"); // (r_scale.x = i, r_scale.y = j)
    r_scale.where(r_scale.y <= r_scale.x);

    // Scale: C[i][j] = beta * C[i][j] for j <= i.
    syrk(r_scale.y, r_scale.x) = cast<num_t>(beta_expr) * syrk(r_scale.y, r_scale.x);

    // === Second update: accumulate alpha * A * A^T in the lower triangle ===
    //
    // RDom over (i, j, k) with a triangular predicate j <= i.
    // This preserves the mathematical behavior of the original kernel
    // while allowing us to choose an efficient loop order via scheduling.
    RDom r(0, n, 0, n, 0, m, "r"); // (r.x = i, r.y = j, r.z = k)
    r.where(r.y <= r.x);

    // For each (i, j <= i, k):
    //   C[i][j] += alpha * A[i][k] * A[j][k]
    //
    // Note: we hoist A[i][k] into a local Expr so that Halide's optimizer
    // can keep it in a register across the inner j-loop after scheduling.
    Expr A_ik = A_param(r.z, r.x);
    Expr A_jk = A_param(r.z, r.y);

    syrk(r.y, r.x) += cast<num_t>(alpha_expr) * A_ik * A_jk;

    // --------------------------------------------------------------------
    //                     SCHEDULING FOR PERFORMANCE
    // --------------------------------------------------------------------

    // We target the host CPU and pick a natural vector width for num_t.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // We compute the final result at the root, as it's the only consumer.
    syrk.compute_root();

    // Pure step: copy original C into syrk.
    //
    // Layout: C(j, i) has j as the fastest-varying dimension in memory.
    // We therefore:
    //   - keep j as the innermost loop,
    //   - parallelize over i (rows),
    //   - vectorize across contiguous j.
    Var jo("jo"), ji("ji");
    syrk
        .split(j, jo, ji, vec_width) // j = jo * vec_width + ji
        .parallel(i)
        .vectorize(ji);

    // First update (scaling by beta on lower triangle).
    //
    // r_scale.x ~ row (i), r_scale.y ~ col (j).
    // We want: for each row i (parallel), sweep contiguously across j.
    syrk.update(0)
        .reorder(r_scale.y, r_scale.x) // innermost: j, outermost: i
        .vectorize(r_scale.y, vec_width)
        .parallel(r_scale.x);

    // Second update (main SYRK accumulation).
    //
    // r.x ~ i (row), r.y ~ j (col), r.z ~ k (inner product index).
    //
    // We mimic the classic BLAS loop structure:
    //   for i
    //     for k
    //       for j
    //
    // by reordering the RDom loops to have:
    //   outermost:  r.x (i)
    //   middle:     r.z (k)
    //   innermost:  r.y (j)
    //
    // This allows re-use of A[i][k] across all j in that row for a fixed (i,k),
    // and keeps writes to C[i][j] contiguous in memory along j.
    syrk.update(1)
        .reorder(r.y, r.z, r.x)    // innermost: j, then k, outermost: i
        .vectorize(r.y, vec_width) // vectorize contiguous C(j, i) across j
        .parallel(r.x);            // parallelize across rows i

    // Compile the kernel to machine code
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

