                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    // Precompute reciprocals on the host to avoid divisions in the Halide loop.
    const num_t inv_n_host = (num_t)1.0 / (num_t)n;
    const num_t inv_m_host = (num_t)1.0 / (num_t)m;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    Expr inv_n = cast<num_t>(inv_n_host);
    Expr inv_m = cast<num_t>(inv_m_host);

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < m; j++)
    //     A[i][j] = ((i*j+1)%n) / n;
    //
    // C array A[i][j] is mapped to Buffer A(j, i) with shape (m, n).
    // We keep the same formula but expressed as integer mod followed by
    // multiplication by 1/n instead of division.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) * inv_n;

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>((i * j + 2) % m) * inv_m;

    // Simple, cache-friendly schedules for the initializers:
    //  - row-major traversal (i outer, j inner)
    //  - parallel over rows
    //  - vectorize over columns
    Target init_target = get_jit_target_from_environment();
    int vec_width = init_target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // Reduction over k runs across the M dimension (first dimension of A).
    RDom k(0, A.dim(0).extent(), "k"); // k over [0, M)

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    // C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as a full N x N computation:
    //   C_new[i][j] = C[i][j]                                     if j > i
    //               = beta * C[i][j] + alpha * sum_k A[i][k] A[j][k]  if j <= i
    //
    // Mapping between C-layout and Halide buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We keep the "only lower triangle is updated" behavior with a select(j <= i, ...),
    // so upper-triangular entries are preserved exactly as in the original C kernel.

    Func syrk("syrk");

    // Promote scalars to Expr once and reuse.
    Expr alpha_expr = cast<num_t>(alpha);
    Expr beta_expr  = cast<num_t>(beta);

    // Load the original C element.
    Expr orig = C_param(j, i);

    // Boolean for lower-triangular check; used in both pure and update definitions.
    Expr is_lower = (j <= i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(is_lower,
                        beta_expr * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for lower triangle only.
    syrk(j, i) += select(is_lower,
                         alpha_expr * A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // ----------------------
    // Optimized Schedule
    // ----------------------
    // Data layout: syrk(j, i) -> inner dimension j (column), outer i (row).
    // We:
    //  - compute the whole matrix at root,
    //  - parallelize across rows (i) to exploit 32-core CPU,
    //  - vectorize across columns (j) for good SIMD utilization,
    //  - for the reduction update, iterate (i outer, k middle, j innermost) to
    //    keep k in a tight inner loop over A's M dimension and j suitable for SIMD.

    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // Compute full result into C at root.
    syrk.compute_root();

    // Pure stage: row-parallel, column-vectorized.
    syrk
        .parallel(i)        // distribute rows across threads
        .vectorize(j, vec_width);

    // Update (reduction) stage:
    // Reorder so that j is the innermost loop (best for vectorization),
    // k is in the middle (good locality along the M dimension),
    // and i is outermost (parallelized across threads).
    syrk.update()
        .reorder(j, k, i)   // innermost -> outermost: j, then k, then i
        .parallel(i)
        .vectorize(j, vec_width);

